<?php
namespace Dth\Crm\Filament\Resources\CustomerResource\RelationManagers; use Filament\Resources\RelationManagers\RelationManager; use Filament\Schemas\Schema; use Filament\Tables\Table; use Filament\Tables\Columns\TextColumn; use Filament\Actions; use Filament\Forms\Components\{Select,TextInput,Textarea,DateTimePicker,Toggle};
class InteractionsRelationManager extends RelationManager {protected static string $relationship='interactions';public static function getTitle($o,string $p):string{return 'Lịch sử chăm sóc';}public function form(Schema $s):Schema{return $s->components([Select::make('interaction_type')->options(['call'=>'Cuộc gọi','email'=>'Email','meeting'=>'Cuộc họp','message'=>'Tin nhắn','support'=>'Hỗ trợ','note'=>'Ghi chú'])->required(),TextInput::make('subject')->label('Chủ đề'),Textarea::make('content')->required()->rows(4),TextInput::make('outcome')->label('Kết quả'),DateTimePicker::make('interaction_at')->default(now())->required(),DateTimePicker::make('next_follow_up_at')->label('Theo dõi tiếp'),Toggle::make('is_support_action')->label('Hành động CSKH')]);}public function table(Table $t):Table{return $t->columns([TextColumn::make('interaction_type')->badge(),TextColumn::make('subject'),TextColumn::make('outcome'),TextColumn::make('interaction_at')->dateTime('d/m/Y H:i'),TextColumn::make('next_follow_up_at')->dateTime('d/m/Y H:i')])->headerActions([Actions\CreateAction::make()->mutateDataUsing(fn($d)=>$d+['staff_id'=>\Dth\Crm\Models\Staff::where('user_id',auth()->id())->value('id')])])->recordActions([Actions\EditAction::make(),Actions\DeleteAction::make()]);}}
